		err := vm.Set("item", item)
		if err != nil {
			return nil, fmt.Errorf("failed to set item variable: %w", err)
		}

		// Run the pre-compiled condition script
		value, err := vm.Run(script)
		if err != nil {
			return nil, fmt.Errorf("failed to execute condition script: %w", err)
		}

		// Convert result to boolean using JavaScript truthiness
		boolResult, err := value.ToBoolean()
		if err != nil {
