// FilterItems filters a slice of maps based on a JavaScript condition script.
// For each item, the script is executed with the item set as a global variable "item".
// Only items for which the script evaluates to true (or truthy) are included in the result.
func FilterItems(conditionScript string, items []map[string]interface{}) ([]map[string]interface{}, error) {
	vm := otto.New()

	// Pre-compile the script once to avoid re-parsing for each item.
	script, err := vm.Compile("", conditionScript)
	if err != nil {
		return nil, fmt.Errorf("failed to compile script: %w", err)
	}

	var result []map[string]interface{}

	for _, item := range items {
		// Set the current item as a global variable named "item".
		err := vm.Set("item", item)
		if err != nil {
			return nil, fmt.Errorf("failed to set item variable: %w", err)
		}

		// Run the compiled script.
		value, err := vm.Run(script)
		if err != nil {
			return nil, fmt.Errorf("failed to execute script: %w", err)
		}

		// Check if the result is truthy.
		isTrue, err := value.ToBoolean()
		if err != nil {
			return nil, fmt.Errorf("failed to convert result to boolean: %w", err)
		}

		if isTrue {
			result = append(result, item)
		}
	}

	return result, nil
}

func main() {
	// Example usage
	items := []map[string]interface{}{
		{"id": 1, "active": true},
		{"id": 2, "active": false},
		{"id": 3, "active": true, "name": "test"},
	}

	script := "item.active == true"

	filtered, err := FilterItems(script, items)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}

	fmt.Println("Filtered items:")
	for _, item := range filtered {
		fmt.Println(item)
	}
}

